      const refill = parseCount(refillStr, lineNo, 'refill', 0)
      const per = parseCount(perStr, lineNo, 'per', 1)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, { type: 'bucket', capacity, refill, per })
    } else if (directive === 'window') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length !== 4) fail(lineNo, 'expected window <name> <limit> <span>')
      const [, name, limitStr, spanStr] = tokens
