      const limit = parseCount(limitStr, lineNo, 'limit', 0)
      const span = parseCount(spanStr, lineNo, 'span', 1)
      if (policies.has(name)) fail(lineNo, `policy ${name} is declared twice`)
      policies.set(name, { type: 'window', limit, span })
    } else if (directive === 'route') {
      if (seenEvent) fail(lineNo, 'declarations must come before the first event')
      if (tokens.length < 3) fail(lineNo, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      if (!NAME_CHARS.test(prefix)) fail(lineNo, `invalid route prefix ${prefix}`)
      if (routePrefixes.has(prefix)) fail(lineNo, `prefix ${prefix} is routed twice`)
      const policyNames = tokens.slice(2)
      for (const pname of policyNames) {
        if (!policies.has(pname)) fail(lineNo, `unknown policy ${pname}`)
      }
      routePrefixes.add(prefix)
      routes.push({ prefix, policyNames })
    } else if (directive === 'event') {
