{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-70Vlxc/src/policies.js","content":"/**
 * The two policy kinds, each keeping one independent state per key. Every
 * count arrives as a `BigInt` so arbitrarily large ticks, capacities and
 * spans never lose precision.
 */

/**
 * A token bucket. Each key starts full and refills by `refill` tokens for
 * every `per` ticks elapsed, tracked as an exact fraction so partial
 * periods never round away.
 */
export class TokenBucket {
  constructor({ capacity, refill, per }) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.max = capacity * per
    this.state = new Map()
  }

  advance(key, tick) {
    let s = this.state.get(key)
    if (!s) {
      this.state.set(key, { numerator: this.max, lastTick: tick })
      return
    }
    const elapsed = tick - s.lastTick
    if (elapsed > 0n) {
      s.numerator += this.refill * elapsed
      if (s.numerator > this.max) s.numerator = this.max
      s.lastTick = tick
    }
  }

  allow(key) {
    return this.state.get(key).numerator >= this.per
  }

  record(key) {
    this.state.get(key).numerator -= this.per
  }
}

/**
 * A sliding window. Each key remembers the ticks of its recorded requests;
 * advancing forgets any that have aged past the span.
 */
export class SlidingWindow {
  constructor({ limit, span }) {
    this.limit = limit
    this.span = span
    this.state = new Map()
  }

  advance(key, tick) {
    let arr = this.state.get(key)
    if (!arr) {
      arr = []
      this.state.set(key, arr)
    }
    const threshold = tick - this.span
    let drop = 0
    while (drop < arr.length && arr[drop] <= threshold) drop++
    if (drop > 0) arr.splice(0, drop)
  }

  allow(key) {
    return BigInt(this.state.get(key).length) < this.limit
  }

  record(key, tick) {
    this.state.get(key).push(tick)
  }
}
"}

